export const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

export const hours = ["9am", "11am", "1pm", "3pm", "5pm", "7pm"];

export const orders = days.flatMap((day, dayIndex) =>
  hours.map((hour, hourIndex) => ({
    day,
    hour,
    orders: Math.round(
      20 + 30 * Math.sin((hourIndex + 1) / 2) + (dayIndex < 5 ? 15 : -10) + ((dayIndex * 7) % 11),
    ),
  })),
);

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { HeatmapChart } from "@/registry/erbium/charts/heatmap-chart";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



const meta = {
  component: HeatmapChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Pass one row per cell, and name the column, row, and value fields with `x`, `y`, and `value`.

```tsx
import { HeatmapChart } from "@/registry/erbium/charts/heatmap-chart";

<HeatmapChart
  ariaLabel="Orders by weekday and hour"
  data={orders}
  x="hour"
  y="day"
  value="orders"
/>;
```

Cells are one color at five strengths, mixed into the page background rather than interpolated, so they follow light and dark themes. `color` changes the base color; `columns` and `rows` fix the order of each axis. With only a few values, use a table or a [Bar Chart](/docs/charts/bar-chart).",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof HeatmapChart>;

export default { ...meta, title: "Charts/Heatmap",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

export const Playground: StoryObj<{ legend: boolean; tooltip: boolean }> = {
  argTypes: { legend: { control: "boolean" }, tooltip: { control: "boolean" } },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { HeatmapChart } from "@/registry/erbium/charts/heatmap-chart";
import { days, hours, orders } from "../examples/data";

export const defaultProps = { legend: true, tooltip: true } satisfies {
  legend: boolean;
  tooltip: boolean;
};

export default function HeatmapChartPlaygroundExample(
  args: { legend: boolean; tooltip: boolean } = defaultProps,
) {
  return (
    <div className="w-full p-4">
      <HeatmapChart
        ariaLabel="Orders by weekday and hour"
        data={orders}
        x="hour"
        y="day"
        value="orders"
        columns={hours}
        rows={days}
        initialWidth={640}
        {...args}
      />
    </div>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

import { HeatmapChart } from "@/registry/erbium/charts/heatmap-chart";
import { days, hours, orders } from "../examples/data";

export const defaultProps = { legend: true, tooltip: true } satisfies {
  legend: boolean;
  tooltip: boolean;
};

export default function HeatmapChartPlaygroundExample(
  args: { legend: boolean; tooltip: boolean } = defaultProps,
) {
  return (
    <div className="w-full p-4">
      <HeatmapChart
        ariaLabel="Orders by weekday and hour"
        data={orders}
        x="hour"
        y="day"
        value="orders"
        columns={hours}
        rows={days}
        initialWidth={640}
        {...args}
      />
    </div>
  );
}

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);
